    A 3D convolution whose stride equals its kernel size (i.e. it operates on non-overlapping patches, as is
    the case for video/patch-embedding layers) is mathematically equivalent to a linear projection applied to
    the flattened patches. This op powers "patch embedding fusion", turning the convolution weight of shape
    ``(out_channels, in_channels, kT, kH, kW)`` into a linear weight of shape
    ``(out_channels, in_channels * kT * kH * kW)``.
    """

    def __init__(self, in_channels: int, kernel_size: tuple[int, int, int]):
        self.in_channels = in_channels
        self.kernel_size = tuple(kernel_size)

    def __repr__(self):
        return f"{self.__class__.__name__}(in_channels={self.in_channels}, kernel_size={self.kernel_size})"

    @torch.no_grad
    def convert(
        self, input_dict: dict[str, torch.Tensor], source_patterns: list[str], target_patterns: list[str], **kwargs
    ) -> dict[str, torch.Tensor]:
        tensors = next(iter(input_dict.values()))
        tensor = tensors[0] if isinstance(tensors, list) else tensors
        target_pattern = target_patterns[0] if target_patterns else next(iter(input_dict))
        # (out_channels, in_channels, kT, kH, kW) -> (out_channels, in_channels * kT * kH * kW)
        reshaped = tensor.reshape(tensor.shape[0], -1).contiguous()
        return {target_pattern: reshaped}

    @property
    def reverse_op(self) -> ConversionOps:
        return LinearToConv3d(self.in_channels, self.kernel_size)


